          "uid": 23,
          "comment": "地点-训练场",
          "content": "{\n    \"训练场\": {\n        \"Environment\": {\n            \"facility_analysis\": {\n                \"Description\": {\n                    \"flooring\": \"整体地面由坚硬耐磨的灰色石质方砖铺设而成。\",\n                    \"structure\": \"训练场分为上下两层结构，功能分区明确。\"\n                },\n                \"floor_1\": {\n                    \"item\": \"基础训练区\",\n                    \"details\": \"一楼作为日常训练与切磋的场所，石质地板上沿墙边摆放着若干木质椅子，供受训者休息或放置衣物。\"\n                },\n                \"floor_2\": {\n                    \"item\": \"高阶禁区\",\n                    \"description\": \"二楼同样铺设着整齐的石砖地板并零散摆放有休息用的椅子。但由于二楼多为高阶对抗训练，危险性极大，故明确规定此处女性止步。\"\n                }\n            }\n        }\n    }\n}",
